class VolumeCalculator:
    def __init__(self, shapes):
        self.shapes = shapes

    def compute_volume(self):
        total_volume = 0
        # Assuming a method volume exists in 3D shape classes
        for shape in self.shapes:
            if hasattr(shape, 'volume'):
                total_volume += shape.volume()
        return total_volume

